// Walk-in cooler compressor controller (known-good build).
// Cabinet probe on A3 (10 mV/°C), compressor on D7, service switch on D4.

const int TEMP_PIN = A3;
const int COMP_PIN = 7;
const int SERVICE_PIN = 4;
const float COOL_ON_C = 8.0f;
const float COOL_OFF_C = 4.0f;
const float FAULT_LOW_C = 0.0f;
const float FAULT_HIGH_C = 60.0f;
const float MV_PER_C = 10.0f;
const unsigned long TICK_MS = 50;
const unsigned long STATUS_MS = 1000;
const unsigned long CONFIRM_MS = 100;

bool cooling = false;
bool onPending = false;
bool offPending = false;
bool servicePending = false;
unsigned long onSince = 0;
unsigned long offSince = 0;
unsigned long serviceSince = 0;
unsigned long lastTick = 0;
unsigned long lastStatus = 0;
float tempC = 0.0f;

float readTempC()
{
    int raw = analogRead(TEMP_PIN);
    float mv = raw * (5000.0f / 1023.0f);
    return mv / MV_PER_C;
}

void setCompressor(bool on)
{
    cooling = on;
    digitalWrite(COMP_PIN, on ? HIGH : LOW);
}

void printStatus()
{
    Serial.print("cooler: ");
    Serial.print(tempC, 1);
    Serial.print(" C comp=");
    Serial.println(cooling ? "ON" : "OFF");
}

void setup()
{
    pinMode(COMP_PIN, OUTPUT);
    pinMode(SERVICE_PIN, INPUT_PULLUP);
    setCompressor(false);
    Serial.begin(9600);
    lastTick = millis();
    lastStatus = millis();
}

void loop()
{
    unsigned long now = millis();

    if (now - lastTick >= TICK_MS)
    {
        lastTick = now;
        tempC = readTempC();
        bool service = (digitalRead(SERVICE_PIN) == LOW);
        bool fault = (tempC < FAULT_LOW_C) || (tempC > FAULT_HIGH_C);

        if (service)
        {
            if (!servicePending)
            {
                servicePending = true;
                serviceSince = now;
            }
        }
        else
        {
            servicePending = false;
        }

        bool serviceActive = servicePending && (now - serviceSince >= CONFIRM_MS);

        if (serviceActive || fault)
        {
            onPending = false;
            offPending = false;
            setCompressor(false);
        }
        else
        {
            if (tempC >= COOL_ON_C)
            {
                if (!onPending)
                {
                    onPending = true;
                    onSince = now;
                }
            }
            else
            {
                onPending = false;
            }

            if (tempC <= COOL_OFF_C)
            {
                if (!offPending)
                {
                    offPending = true;
                    offSince = now;
                }
            }
            else
            {
                offPending = false;
            }

            if (onPending && (now - onSince >= CONFIRM_MS))
            {
                setCompressor(true);
            }
            else if (offPending && (now - offSince >= CONFIRM_MS))
            {
                setCompressor(false);
            }
        }
    }

    if (now - lastStatus >= STATUS_MS)
    {
        lastStatus = now;
        printStatus();
    }
}
